#!/usr/bin/env node
/**
 * Append per-backend latency rows for trend analysis.
 * Input: test-results/per-backend-latency.json (generated by verify-audio-backend-latency.js with PER_BACKEND_LATENCY_JSON)
 * Output CSV: dev/web_viewer/perf-backend-latency-history.csv
 * Columns: isoTimestamp,gitSha,backend,samples,p50,p95,p50Budget,p95Budget,ok
 */
const fs = require('fs');
const path = require('path');
const src = path.join(process.cwd(),'test-results','per-backend-latency.json');
if(!fs.existsSync(src)) { console.error('No per-backend-latency.json, skipping backend history append'); process.exit(0); }
let j; try { j = JSON.parse(fs.readFileSync(src,'utf8')); } catch { console.error('Failed to parse per-backend-latency.json'); process.exit(1);} 
const sha = process.env.GITHUB_SHA || 'local';
const historyPath = path.join(process.cwd(),'dev','web_viewer','perf-backend-latency-history.csv');
if(!fs.existsSync(historyPath)) {
  fs.writeFileSync(historyPath,'isoTimestamp,gitSha,backend,samples,p50,p95,p50Budget,p95Budget,ok\n');
}
const now = new Date().toISOString();
(j.rows||[]).forEach(r => {
  const ok = !j.violations.some(v => v.backend === r.backend && (v.metric==='p50' || v.metric==='p95' || v.metric==='samples'));
  const row = [now,sha,r.backend,r.samples||0,r.p50||0,r.p95||0,r.p50Budget||0,r.p95Budget||0,ok?1:0].join(',');
  fs.appendFileSync(historyPath,row+'\n');
  console.log('Appended backend latency row:', row);
});
